455:     IFACEMETHODIMP GetState(_In_opt_ IShellItemArray* items, _In_ BOOL okToBeSlow, _Out_ EXPCMDSTATE* cmdState) override {
456:         // Provide state of File Explorer context menu entry
457:         // Hide it if registry setting indicates that it should be disabled or file is unsupported, else it is enabled
458: 
459:         if (!okToBeSlow) {
460:             *cmdState = ECS_DISABLED;
461:             // returning E_PENDING requests that a new instance of this object be called back
462:             // on a background thread so that it can do work that might be slow
463:             return E_PENDING;
464:         }
465: 
466: #ifdef MEDIAINFO_QT
467:         auto shellExtension{ RegGetBool(HKEY_CURRENT_USER, L"Software\\MediaArea.net\\MediaInfo", L"shellExtension") };
468:         if (shellExtension.has_value() && !shellExtension.value())
469: #else
470:         auto ShellExtension{ RegGetDword(HKEY_CURRENT_USER, L"Software\\MediaArea\\MediaInfo", L"ShellExtension") };
471:         auto ShellExtension_Folder{ RegGetDword(HKEY_CURRENT_USER, L"Software\\MediaArea\\MediaInfo", L"ShellExtension_Folder") };
472:         if (ShellExtension.has_value() && !ShellExtension.value() && ShellExtension_Folder.has_value() && !ShellExtension_Folder.value())
473: #endif // MEDIAINFO_QT
474:         {
475:             *cmdState = ECS_HIDDEN;
476:             return S_OK;
477:         }
478: 
479:         // Check if it is a folder or supported file extension
480:         bool is_folder{ false };
481:         bool is_supported_extension{ false };
482:         if (items) {
483:             DWORD count{};
484:             RETURN_IF_FAILED(items->GetCount(&count));
485:             if (count > 0) {
486:                 winrt::com_ptr<IShellItem> item;
487:                 if (SUCCEEDED(items->GetItemAt(0, item.put()))) {
488:                     SFGAOF attribute{};
489:                     if (SUCCEEDED(item->GetAttributes(SFGAO_FOLDER | SFGAO_STREAM, &attribute))) {
490:                         if ((attribute & SFGAO_FOLDER) && !(attribute & SFGAO_STREAM))
491:                             is_folder = true;
492:                         else {
493:                             wil::unique_cotaskmem_string path;
494:                             if (SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &path))) {
495:                                 std::filesystem::path filepath{ path.get() };
496:                                 // resolve shortcuts
497:                                 if (filepath.extension().string() == ".url") {
498:                                     std::string url;
499:                                     if (ExtractUrlFromShortcut(filepath, url))
500:                                         is_supported_extension = IsSupportedFileExtension(ExtractFileExtensionFromUrl(url));
501:                                 }
502:                                 else {
503:                                     if (filepath.extension().string() == ".lnk") {
504:                                         WCHAR target_path[MAX_PATH];
505:                                         if (SUCCEEDED(ResolveIt(nullptr, filepath.wstring().c_str(), target_path, sizeof(target_path))))
506:                                             filepath = target_path;
507:                                     }
508:                                     if (std::filesystem::is_directory(filepath))
509:                                         is_folder = true;
510:                                     else
511:                                         is_supported_extension = IsSupportedFileExtension(filepath.extension().string());
512:                                 }
513:                             }
514:                         }
515:                     }
516:                 }
517:             }
518:         }
519: 
520:         if (!is_supported_extension && !is_folder) {
521:             *cmdState = ECS_HIDDEN;
522:             return S_OK;
523:         }
524: 
525: #ifndef MEDIAINFO_QT
526:         if ((ShellExtension.has_value() && !ShellExtension.value() && !is_folder) || (ShellExtension_Folder.has_value() && !ShellExtension_Folder.value() && is_folder)) {
527:             *cmdState = ECS_HIDDEN;
528:             return S_OK;
529:         }
530: #endif // MEDIAINFO_QT
531: 
532:         // Default enabled if not disabled
533:         *cmdState = ECS_ENABLED;
534:         return S_OK;
