547:     IFACEMETHODIMP Invoke(_In_opt_ IShellItemArray* items, _In_opt_ IBindCtx* bindCtx) override {
548:         // Process items passed by File Explorer when context menu entry is invoked
549:         UNREFERENCED_PARAMETER(bindCtx);
550: 
551:         // Return if no items
552:         if (!items)
553:             return S_OK;
554: 
555:         // Get count
556:         DWORD count{};
557:         RETURN_IF_FAILED(items->GetCount(&count));
558: 
559:         // Get path to application exe
560:         std::filesystem::path module_path{ wil::GetModuleFileNameW<std::wstring>(wil::GetModuleInstanceHandle()) };
561:         module_path = module_path.remove_filename();
562:         module_path /= exe_filename;
563: 
564:         // Option for separate instance
565:         bool separate_instance{ false };
566: #ifdef MEDIAINFO_QT
567:         auto shellExtension_separateInstance{ RegGetBool(HKEY_CURRENT_USER, L"Software\\MediaArea.net\\MediaInfo", L"shellExtension_separateInstance") };
568:         if (shellExtension_separateInstance.has_value() && shellExtension_separateInstance.value())
569: #else
570:         auto ShellExtension_SeparateInstance{ RegGetDword(HKEY_CURRENT_USER, L"Software\\MediaArea\\MediaInfo", L"ShellExtension_SeparateInstance") };
571:         if (ShellExtension_SeparateInstance.has_value() && ShellExtension_SeparateInstance.value())
572: #endif // MEDIAINFO_QT
573:         {
574:             separate_instance = true;
575:         }
576:         if (separate_instance) {
577:             // Invoke application, one instance per item
578:             for (DWORD i = 0; i < count; ++i) {
579:                 winrt::com_ptr<IShellItem> item;
580:                 auto result = items->GetItemAt(i, item.put());
581:                 if (SUCCEEDED(result)) {
582:                     wil::unique_cotaskmem_string path;
583:                     result = item->GetDisplayName(SIGDN_FILESYSPATH, &path);
584:                     if (SUCCEEDED(result)) {
585:                         std::filesystem::path filepath{ path.get() };
586:                         // Resolve shortcuts
587:                         if (filepath.extension().string() == ".url") {
588:                             std::string url;
589:                             if (ExtractUrlFromShortcut(filepath, url))
590:                                 filepath = url;
591:                         }
592:                         if (filepath.extension().string() == ".lnk") {
593:                             WCHAR target_path[MAX_PATH];
594:                             if (SUCCEEDED(ResolveIt(nullptr, filepath.wstring().c_str(), target_path, sizeof(target_path))))
595:                                 filepath = target_path;
596:                         }
597:                         auto command{ wil::str_printf<std::wstring>(LR"-("%s" %s)-", module_path.c_str(), QuoteForCommandLineArg(filepath.wstring()).c_str()) };
598:                         wil::unique_process_information process_info;
599:                         STARTUPINFOW startup_info = { sizeof(startup_info) };
600:                         RETURN_IF_WIN32_BOOL_FALSE(CreateProcessW(
601:                             nullptr,
602:                             command.data(),
603:                             nullptr /* lpProcessAttributes */,
604:                             nullptr /* lpThreadAttributes */,
605:                             false /* bInheritHandles */,
606:                             CREATE_NO_WINDOW,
607:                             nullptr,
608:                             nullptr,
609:                             &startup_info,
610:                             &process_info));
611:                     }
612:                 }
613:             }
614:             return S_OK;
615:         }
616: 
617:         // Prepare cmd line string to invoke application ("path\to\application.exe" "path\to\firstitem" "path\to\nextitem" ...)
618:         auto command{ wil::str_printf<std::wstring>(LR"-("%s")-", module_path.c_str()) }; // Path to application.exe
619:         // Add multiple selected files/folders to cmd line as parameters
620:         for (DWORD i = 0; i < count; ++i) {
621:             winrt::com_ptr<IShellItem> item;
622:             auto result = items->GetItemAt(i, item.put());
623:             if (SUCCEEDED(result)) {
624:                 wil::unique_cotaskmem_string path;
625:                 result = item->GetDisplayName(SIGDN_FILESYSPATH, &path);
626:                 if (SUCCEEDED(result)) {
627:                     std::filesystem::path filepath{ path.get() };
628:                     // Resolve shortcuts
629:                     if (filepath.extension().string() == ".url") {
630:                         std::string url;
631:                         if (ExtractUrlFromShortcut(filepath, url))
632:                             filepath = url;
633:                     }
634:                     if (filepath.extension().string() == ".lnk") {
635:                         WCHAR target_path[MAX_PATH];
636:                         if (SUCCEEDED(ResolveIt(nullptr, filepath.wstring().c_str(), target_path, sizeof(target_path))))
637:                             filepath = target_path;
638:                     }
639:                     // Append the item path to the existing command, adding quotes and escapes as needed
640:                     command = wil::str_printf<std::wstring>(LR"-(%s %s)-", command.c_str(), QuoteForCommandLineArg(filepath.wstring()).c_str());
641:                 }
642:             }
643:         }
644: 
645:         // Invoke application using CreateProcess with the command string prepared above
646:         wil::unique_process_information process_info;
647:         STARTUPINFOW startup_info = { sizeof(startup_info) };
648:         RETURN_IF_WIN32_BOOL_FALSE(CreateProcessW(
649:             nullptr,
650:             command.data(),
651:             nullptr /* lpProcessAttributes */,
652:             nullptr /* lpThreadAttributes */,
653:             false /* bInheritHandles */,
654:             CREATE_NO_WINDOW,
655:             nullptr,
656:             nullptr,
657:             &startup_info,
658:             &process_info));
659: 
660:         return S_OK;
661:     }
662: };
