    wxFile FB2;
    FB2.Create((FileName+__T(".header")).c_str(), true);
    FB2.Write(Tout, Capture);

    //Purge
    delete [] Tout;
    MessageBox(Handle, Prefs->Translate(__T("Send HeaderFile")).c_str(), Prefs->Translate(__T("Header file")).c_str(), 0);
